      "properties": {
        "data": {
          "type": "object",
          "properties": {
            "rows": {
              "type": "array",
              "items": {
                "type": "object",
                "properties": {
                  "vault_id": {
                    "type": "string",
                    "example": ""
                  },
                  "vault_address": {
                    "type": "string",
                    "example": ""
                  },
                  "vault_type": {
                    "type": "string",
                    "example": "protocol"
                  },
                  "vault_name": {
                    "type": "string",
                    "example": "Orderly OmniVault"
                  },
                  "description": {
                    "type": "string",
                    "example": "Earn passive yields effortlessly, no trading expertise required. Deposit..."
                  },
                  "sp_address": {
                    "type": "string",
                    "example": "xxxxxxx"
                  },
                  "sp_name": {
                    "type": "string",
                    "description": "return null if not set",
                    "example": "yyyy"
                  },
                  "asset": {
                    "type": "string",
                    "example": "USDC"
                  },
                  "vault_age": {
                    "type": "number",
                    "description": "From period 0 start time to current time; in terms of day.",
                    "example": 180
                  },
