                    "example": "PERP_WOO_USDC"
                  },
                  "side": {
                    "type": "string",
                    "example": "BUY"
                  },
                  "quantity": {
                    "type": "number",
                    "example": 20
                  },
                  "price": {
                    "type": "number",
                    "example": 0.67772
                  },
                  "executed_quantity": {
                    "type": "number",
                    "example": 0
                  },
                  "total_executed_quantity": {
                    "type": "number",
                    "example": 0
                  },
                  "average_executed_price": {
                    "type": "number",
                    "example": 0
                  },
